26	// The fixture recorder (DEVDESK-511, step 7). RecordFixtures replays the request
27	// of each recorded fixture against the bench and writes the redacted answer back
28	// to the same file. It sends the bench credentials, so everything that could go
29	// wrong is refused before the first fixture request, and nothing is written
30	// unless every answer passed: GET only, a closed list of paths, loopback origins
31	// only, no redirection, a leak check of what will be written.
32	
33	const (
34		// recordedBy is the value of the "recorded-by" header the recorder sets.
35		recordedBy = "nexus-bench record"
36		// recordedFileMode and recordedDirMode are the modes of a written fixture.
37		recordedFileMode os.FileMode = 0o644
38		recordedDirMode  os.FileMode = 0o755
39		// recordedDateLayout is the date of the "measured" header.
40		recordedDateLayout = "2006-01-02"
41	
42		benchUpCall = "run `mise run nexus-bench:up` so the bench runs the version the descriptor names"
43	)
44	
45	// RecordOptions says what to record and against which bench.
46	type RecordOptions struct {
47		// Origins maps the Host of a fixture ("127.0.0.1:30481") to the base URL that
48		// reaches it. Each key must be a loopback host:port of the descriptor and each
49		// URL a loopback origin (IsLoopbackRESTHost), no user information. The REST
50		// origin (first host of the descriptor, REST node port) is required: the data
51		// set is compared through it.
52		Origins    map[string]string
53		Descriptor Descriptor
54		Secrets    Secrets
55		// Dir is the folder of the campaigns; empty means nexusfixture.SourceDir().
56		Dir string
57		// Campaigns limits the run to these campaigns; empty means every folder of Dir.
58		Campaigns []string
59		// Only is an optional glob (path.Match) on fixture names, without ".http".
60		Only string
61		// Now gives the date of the "measured" header; nil means time.Now.
62		Now func() time.Time
63		// DenyTerms are extra terms no written fixture may hold (the external deny list).
64		DenyTerms []string
65	}
