220	// planFixture reads one fixture file. It returns the reason when the fixture is
221	// skipped, an error when it must not be sent.
222	func planFixture(o RecordOptions, fsys fs.FS, filePath, campaign, fileName string) (recordJob, string, error) {
223		label := campaign + "/" + strings.TrimSuffix(fileName, ".http")
224		data, err := fs.ReadFile(fsys, path.Join(campaign, fileName))
225		if err != nil {
226			return recordJob{}, "", recordError(label+" cannot be read", "check the file", err)
227		}
228		f, err := nexusfixture.Parse(campaign, fileName, data)
229		if err != nil {
230			return recordJob{}, "", recordError(label+" is not a valid fixture", "fix the file: "+err.Error(), err)
231		}
232		if reason, ok := strings.CutPrefix(f.Meta.Record, "skip"); ok {
233			return recordJob{}, strings.TrimSpace(strings.TrimPrefix(reason, ":")), nil
234		}
235		if len(f.Exchanges) != 1 {
236			return recordJob{}, fmt.Sprintf("holds %d exchanges, only one is recorded yet", len(f.Exchanges)), nil
237		}
238		// The file is scanned as it stands: a request header outside Host, the
239		// credentials and Accept, or a query other than n and last, refuses it.
240		if leaks := nexusfixture.CheckLeaks(label, data, recordTerms(o)); len(leaks) > 0 {
241			return recordJob{}, "", recordError(label+" is refused before it is sent: "+describeLeaks(leaks), "fix the file", nil)
242		}
243		ex := f.Exchanges[0]
244		if reason := refusedRequest(ex.Method, ex.Target); reason != "" {
245			return recordJob{}, "", recordError(label+" asks for something the recorder does not send ("+reason+")", "record only GET requests of the closed list of paths", nil)
246		}
247		origin, ok := o.Origins[ex.Host]
248		if !ok {
249			return recordJob{}, "", recordError(label+" is recorded on "+ex.Host+", which has no origin", "give the origin of this host:port", nil)
250		}
251		job := recordJob{campaign: campaign, name: label, path: filePath, current: f, origin: origin}
252		switch f.Identity {
253		case nexusfixture.Admin:
254			job.user, job.password = REDACTED, o.Secrets.AdminPassword
255		case nexusfixture.Pull:
256			job.user, job.password = REDACTED, o.Secrets.PullPassword
257		}
258		if job.user != "" && job.password == "" {
259			return recordJob{}, "", recordError("the bench has no stored password for "+job.user+", the account of "+label, upCheck, nil)
260		}
261		return job, "", nil
262	}
