556	// holdsTerm searches the raw answer, whatever the redaction would drop or hide
557	// (a header outside the allowlist, an HTML body), for a term in the forms it can
558	// take: as is, in another case, URL-escaped, JSON-escaped.
559	func holdsTerm(header http.Header, body []byte, terms []string) bool {
560		var raw strings.Builder
561		for name, values := range header {
562			raw.WriteString(name + ": " + strings.Join(values, "\n") + "\n")
563		}
564		raw.Write(body)
565		text := strings.ToLower(raw.String())
566		jsonEscaper := strings.NewReplacer(`\`, `\\`, `"`, `\"`, `/`, `\/`)
567		for _, term := range terms {
568			if term == "" {
569				continue
570			}
571			for _, v := range []string{term, url.QueryEscape(term), url.PathEscape(term), jsonEscaper.Replace(term)} {
572				if strings.Contains(text, strings.ToLower(v)) {
573					return true
574				}
575			}
576		}
577		return false
578	}
