136	func (b *recBench) serve(w http.ResponseWriter, r *http.Request) {
137		user, pass, basic := r.BasicAuth()
138		b.mu.Lock()
139		b.seen = append(b.seen, recSeen{method: r.Method, uri: r.RequestURI, user: user, header: r.Header.Clone()})
140		answer, found := b.answers[user+" "+r.RequestURI]
141		server := b.server
142		b.mu.Unlock()
143	
144		if r.Header.Get("Authorization") != "" && (!basic || pass != recPasswords[user]) {
145			w.WriteHeader(http.StatusUnauthorized)
146			return
147		}
148		h := w.Header()
149		if server != "" {
150			h.Set("Server", server)
151		}
152		h.Set("Set-Cookie", "NXSESSIONID=rec-session; Path=/")
153		h.Set("X-Content-Type-Options", "nosniff")
154		if !found {
155			answer = recAnswer{status: http.StatusNotFound, contentType: "application/json", body: `{"message":"no answer registered"}`}
156		}
157		if answer.contentType != "" {
158			h.Set("Content-Type", answer.contentType)
159		}
160		for k, v := range answer.header {
161			h[k] = v
162		}
163		if answer.status == 0 {
164			answer.status = http.StatusOK
165		}
166		w.WriteHeader(answer.status)
167		_, _ = w.Write([]byte(answer.body))
168	}
