346			e.t.Errorf("the error %q does not name the fixture %q", err, fixture)
347		}
348		if len(rep.Written) != 0 {
349			e.t.Errorf("Written = %v after a refusal, want none", rep.Written)
350		}
351		requireSameFiles(e.t, before, recSnapshot(e.t, e.dir))
352		return be
353	}
