357	func requireRecordRefusal(t *testing.T, err error) *BenchError {
358		t.Helper()
359		if err == nil {
360			t.Fatal("RecordFixtures succeeded, want a refusal")
361		}
362		var be *BenchError
363		if !errors.As(err, &be) {
364			t.Fatalf("error %T is not a *BenchError: %v", err, err)
365		}
366		if be.Cause == "" || be.Check == "" {
367			t.Errorf("the BenchError is incomplete: cause %q, check %q", be.Cause, be.Check)
368		}
369		for _, secret := range recExact() {
370			if strings.Contains(err.Error(), secret) {
371				t.Errorf("the error text carries a secret: %q", err)
372			}
373		}
374		return be
375	}
