382	func recSnapshot(t *testing.T, dir string) map[string]recFile {
383		t.Helper()
384		out := map[string]recFile{}
385		err := filepath.WalkDir(dir, func(path string, d os.DirEntry, err error) error {
386			if err != nil || d.IsDir() {
387				return err
388			}
389			data, err := os.ReadFile(path) //nolint:gosec // a file of the test's own temporary folder
390			if err != nil {
391				return err
392			}
393			info, err := d.Info()
394			if err != nil {
395				return err
396			}
397			out[path] = recFile{data: data, mod: info.ModTime()}
398			return nil
399		})
400		if err != nil {
401			t.Fatal(err)
402		}
403		return out
