406	func requireSameFiles(t *testing.T, before, after map[string]recFile) {
407		t.Helper()
408		for path, was := range before {
409			now, ok := after[path]
410			switch {
411			case !ok:
412				t.Errorf("%s disappeared", path)
413			case !bytes.Equal(was.data, now.data):
414				t.Errorf("%s was rewritten:\n%s", path, now.data)
415			case !was.mod.Equal(now.mod):
416				t.Errorf("%s was touched (modification time %v, was %v)", path, now.mod, was.mod)
417			}
418		}
419		for path := range after {
420			if _, ok := before[path]; !ok {
421				t.Errorf("%s appeared (a temporary file left behind?)", path)
422			}
423		}
424	}
