445	// requireRecorded checks a file the recorder wrote: it reads back, writes back
446	// to the same bytes, leaks nothing and says who wrote it and when.
447	func requireRecorded(t *testing.T, path, measured string) nexusfixture.Fixture {
448		t.Helper()
449		data := mustRead(t, path)
450		f := parseRecorded(t, path)
451		if got := nexusfixture.Format(f); !bytes.Equal(got, data) {
452			t.Errorf("Format(Parse(file)) differs from the file:\n%s\n--- want\n%s", got, data)
453		}
454		if leaks := nexusfixture.CheckLeaks(f.Name, data, recExact()); len(leaks) != 0 {
455			t.Errorf("the recorded file leaks: %+v", leaks)
456		}
457		m := f.Meta
458		if m.RecordedBy != recRecordedBy {
459			t.Errorf("recorded-by = %q, want %q", m.RecordedBy, recRecordedBy)
460		}
461		if m.Measured != measured {
462			t.Errorf("measured = %q, want %q", m.Measured, measured)
463		}
464		if m.NexusVersion != "3.98.1-01" || m.Edition != "COMMUNITY" {
465			t.Errorf("nexus = %s %s, want 3.98.1-01 COMMUNITY", m.NexusVersion, m.Edition)
466		}
467		if m.Record == nexusfixture.RecordPending {
468			t.Error("the fixture is still pending")
469		}
470		if len(f.Exchanges) != 1 || f.Exchanges[0].Status == 0 {
471			t.Fatalf("exchanges = %+v, want one with an answer", f.Exchanges)
472		}
473		return f
474	}
