115	// recBench is one origin of the bench: an httptest server that answers what a
116	// test registered, keyed by account and request URI ("" for anonymous), checks
117	// the Basic credentials it receives against the passwords of recPasswords, adds
118	// to every answer a session cookie and a header the fixtures must drop, and
119	// remembers every request.
120	type recBench struct {
121		srv     *httptest.Server
122		mu      sync.Mutex
123		seen    []recSeen
124		answers map[string]recAnswer
125		server  string
126	}
127	
128	func newRecBench(t *testing.T) *recBench {
129		t.Helper()
130		b := &recBench{answers: map[string]recAnswer{}, server: recServer}
131		b.srv = httptest.NewServer(http.HandlerFunc(b.serve))
132		t.Cleanup(b.srv.Close)
133		return b
134	}
135	
136	func (b *recBench) serve(w http.ResponseWriter, r *http.Request) {
137		user, pass, basic := r.BasicAuth()
138		b.mu.Lock()
139		b.seen = append(b.seen, recSeen{method: r.Method, uri: r.RequestURI, user: user, header: r.Header.Clone()})
140		answer, found := b.answers[user+" "+r.RequestURI]
141		server := b.server
142		b.mu.Unlock()
143	
144		if r.Header.Get("Authorization") != "" && (!basic || pass != recPasswords[user]) {
145			w.WriteHeader(http.StatusUnauthorized)
146			return
147		}
148		h := w.Header()
149		if server != "" {
150			h.Set("Server", server)
151		}
152		h.Set("Set-Cookie", "NXSESSIONID=rec-session; Path=/")
153		h.Set("X-Content-Type-Options", "nosniff")
154		if !found {
155			answer = recAnswer{status: http.StatusNotFound, contentType: "application/json", body: `{"message":"no answer registered"}`}
156		}
157		if answer.contentType != "" {
158			h.Set("Content-Type", answer.contentType)
159		}
160		for k, v := range answer.header {
161			h[k] = v
162		}
163		if answer.status == 0 {
164			answer.status = http.StatusOK
165		}
166		w.WriteHeader(answer.status)
167		_, _ = w.Write([]byte(answer.body))
168	}
169	
170	func (b *recBench) answer(user, uri string, a recAnswer) {
171		b.mu.Lock()
172		defer b.mu.Unlock()
173		b.answers[user+" "+uri] = a
174	}
