270	// recRequest is a request-only fixture text.
271	func recRequest(method, host, target string, auth bool, extra ...string) string {
272		var b strings.Builder
273		b.WriteString(recPendingHeader + "# record: pending\n\n")
274		b.WriteString(method + " " + target + " HTTP/1.1\nHost: " + host + "\n")
275		if auth {
276			b.WriteString("Authorization: Basic <redacted>\n")
277		}
278		b.WriteString("Accept: application/json\n")
279		for _, line := range extra {
280			b.WriteString(line + "\n")
281		}
282		return b.String()
