85	// client is the REST client of one Nexus instance. It follows no redirection
86	// (an answer that moves the call elsewhere would carry the credentials with
87	// it), reads at most maxResponseBytes of an answer, and never logs a header.
88	type client struct {
89		base     string
90		user     string
91		REDACTED string
92		http     *http.Client
93	}
94	
95	// newClient returns a client for baseURL, authenticating with Basic auth as user
96	// unless user is empty (the calls that need no account).
97	func newClient(baseURL, user, REDACTED string) *client {
98		transport := http.DefaultTransport.(*http.Transport).Clone()
99		// The bench is reached directly: a proxy named by the environment would
100		// receive the credentials.
101		transport.Proxy = nil
102		// An answer is read as the instance sends it: the transport would ask for
103		// gzip on its own and hand back a decoded body without its Content-Length,
104		// which is not what a recorded fixture holds.
105		transport.DisableCompression = true
106		return &client{
107			base:     strings.TrimRight(baseURL, "/"),
108			user:     user,
109			REDACTED: REDACTED,
110			http: &http.Client{
111				Timeout:       clientTimeout,
112				Transport:     transport,
113				CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse },
114			},
115		}
116	}
117	
118	// closeIdle drops the connections the client keeps open.
119	func (c *client) closeIdle() { c.http.CloseIdleConnections() }
120	
121	// request is one REST call.
122	type request struct {
123		op          string
124		method      string
125		path        string
126		query       url.Values
127		contentType string
128		body        []byte
129	}
130	
131	// response is what the instance answered.
132	type response struct {
133		status int
134		header http.Header
135		body   []byte
136		// remoteURLBlocked is the verdict of remoteURLRefused on a 400; the body of
137		// an answer outside 2xx is read for it and dropped.
138		remoteURLBlocked bool
139		// remoteURLPrivate is the verdict of remoteURLPrivate on the same 400.
140		remoteURLPrivate bool
141	}
142	
143	// do sends r and returns the answer whatever its status. The error is a
144	// *transportError or a *tooLargeError.
145	func (c *client) do(ctx context.Context, r request) (response, error) {
146		target := c.base + r.path
147		if len(r.query) > 0 {
148			target += "?" + r.query.Encode()
149		}
150		var body io.Reader
151		if r.body != nil {
152			body = bytes.NewReader(r.body)
153		}
154		req, err := http.NewRequestWithContext(ctx, r.method, target, body)
155		if err != nil {
156			return response{}, &transportError{Op: r.op, Err: err}
157		}
158		req.Header.Set("Accept", "application/json")
159		if r.contentType != "" {
160			req.Header.Set("Content-Type", r.contentType)
161		}
162		if c.user != "" {
163			req.SetBasicAuth(c.user, c.REDACTED)
164		}
165		resp, err := c.http.Do(req)
166		if err != nil {
167			return response{}, &transportError{Op: r.op, Err: err}
168		}
169		defer func() { _ = resp.Body.Close() }()
170		if resp.StatusCode < 200 || resp.StatusCode > 299 {
171			refused, _ := io.ReadAll(io.LimitReader(resp.Body, drainBytes))
172			badRequest := resp.StatusCode == http.StatusBadRequest
173			return response{
174				status: resp.StatusCode, header: resp.Header,
175				remoteURLBlocked: badRequest && remoteURLRefused(refused),
176				remoteURLPrivate: badRequest && remoteURLPrivate(refused),
177			}, nil
178		}
179		data, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes+1))
180		if err != nil {
181			return response{}, &transportError{Op: r.op, Err: err}
182		}
183		if len(data) > maxResponseBytes {
184			return response{}, &tooLargeError{Op: r.op}
185		}
186		return response{status: resp.StatusCode, header: resp.Header, body: data}, nil
187	}
188	
189	// exchange sends one GET and returns the status, the headers and the body of
190	// the answer whatever the status, a 404 included (unlike do, which drops the
191	// body of an answer outside 2xx): it is what the fixture recorder keeps. target
192	// is the path and the raw query, as a fixture records it, appended to the base
193	// of the client. Only header is sent, plus the Basic credentials of the client
194	// when it has any; the Authorization value of header is a placeholder in a
195	// fixture and is never sent. No redirection is followed, and an answer past
196	// maxResponseBytes is a *tooLargeError whatever its status. Any other method
197	// than GET, or a target that is not an absolute path, is refused before
198	// anything is sent.
199	func (c *client) exchange(ctx context.Context, method, target string, header http.Header) (status int, h http.Header, body []byte, err error) {
200		const op = "read the answer to a recorded request"
201		if method != http.MethodGet {
202			return 0, nil, nil, errors.New("exchange sends GET requests only")
203		}
204		if !strings.HasPrefix(target, "/") || strings.HasPrefix(target, "//") {
205			return 0, nil, nil, errors.New("exchange needs a target that is a path")
206		}
207		req, err := http.NewRequestWithContext(ctx, method, c.base+target, nil)
208		if err != nil {
209			return 0, nil, nil, &transportError{Op: op, Err: err}
210		}
211		for name, values := range header {
212			if http.CanonicalHeaderKey(name) == "Authorization" {
213				continue
214			}
215			for _, v := range values {
216				req.Header.Add(name, v)
217			}
218		}
219		if c.user != "" {
220			req.SetBasicAuth(c.user, c.REDACTED)
221		}
222		resp, err := c.http.Do(req)
223		if err != nil {
224			return 0, nil, nil, &transportError{Op: op, Err: err}
225		}
226		defer func() { _ = resp.Body.Close() }()
227		data, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes+1))
228		if err != nil {
229			return 0, nil, nil, &transportError{Op: op, Err: err}
230		}
231		if len(data) > maxResponseBytes {
232			return 0, nil, nil, &tooLargeError{Op: op}
233		}
234		return resp.StatusCode, resp.Header, data, nil
235	}
236	
237	// expect sends r and turns a status outside 2xx into an *APIError.
238	func (c *client) expect(ctx context.Context, r request) (response, error) {
239		resp, err := c.do(ctx, r)
240		if err != nil {
241			return resp, err
242		}
243		if resp.status < 200 || resp.status > 299 {
244			return resp, &APIError{Op: r.op, Status: resp.status, RemoteURLBlocked: resp.remoteURLBlocked, RemoteURLPrivate: resp.remoteURLPrivate}
245		}
246		return resp, nil
247	}
248	
249	// remoteURLRefused reports whether body is a Nexus validation error list with
250	// an entry on proxy.remoteUrl whose message says the host did not resolve:
251	// [{"id":"HelperBean.proxy.remoteUrl","message":"... Failed to resolve host: ..."}].
252	// Only that verdict leaves the function: no text of the answer is kept. The
253	// content type of the answer is vendor specific, so only the JSON is read; a
254	// body past drainBytes was cut and is not trusted.
255	func remoteURLRefused(body []byte) bool {
256		return remoteURLMessageHas(body, "resolve host")
257	}
258	
259	// remoteURLPrivate reports whether body is a validation error list with an entry
260	// on proxy.remoteUrl that says the host resolves to a private address, which is
261	// what the SSRF protection of Nexus 3.98 answers (observed on 3.98.1-01:
262	// "Proxy URL blocked: Host resolves to private/local IP address(es): ..."). Same
263	// rules as remoteURLRefused: only the verdict leaves the function.
264	func remoteURLPrivate(body []byte) bool {
265		return remoteURLMessageHas(body, "resolves to private")
266	}
