type gzipBench struct {
	srv  *httptest.Server
	mu   sync.Mutex
	seen []string
}

func newGzipBench(t *testing.T, body string) *gzipBench {
	t.Helper()
	b := &gzipBench{}
	b.srv = httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		accepted := r.Header.Get("Accept-Encoding")
